#include "ir.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <errno.h>
#include <math.h>

static char *dupstr(const char*s){size_t n=strlen(s)+1;char*p=malloc(n);if(p)memcpy(p,s,n);return p;}

static const char *const opcode_names[R6_OP_COUNT] = {
 "nop","load_const","load_var","store_var","decl_var","add","sub","mul","div","mod","eq","ne","lt","le","gt","ge","and_op","or_op","not_op","neg","begin_block","end_block","call","ret","jump","jump_if_false","alloc","free","db_get","db_set","db_all","db_where","http_response","label","copy","arg","load_field","store_field","switch_op","type_info","list_create","list_push","list_get","list_set","list_len","list_pop","map_create","map_set","map_get","map_has","map_delete","map_keys","result_ok","result_err","result_unwrap","result_is_ok","result_unwrap_err","union_create","union_get_tag","union_get_data",
 "bit_and","bit_or","bit_xor","shl","shr","bit_not"
};
const char *r6_opcode_name(R6Opcode op) { return op >= 0 && op < R6_OP_COUNT ? opcode_names[op] : "<invalid>"; }

typedef enum { J_OBJ, J_ARR, J_STR, J_NUM, J_TRUE, J_FALSE, J_NULL } JKind;
typedef struct JNode { JKind kind; size_t line,col,slen; char *s; struct JNode **v; size_t n,cap; } JNode;
/* D-M1-64: the JSON tree is a few million small nodes, strings and arrays.
 * They come from 1 MiB chunks and go back together when the parse ends, so
 * neither the parse nor the teardown pays one malloc/free per node. */
typedef struct Chunk { struct Chunk *next; size_t used, cap; unsigned char data[]; } Chunk;
typedef struct { const char *p; size_t n,i,line,col; R6Diagnostic *d; Chunk *chunks; } Parser;
static void *arena_alloc(Parser *p,size_t n){Chunk*c=p->chunks;n=(n+15)&~(size_t)15;if(!c||c->cap-c->used<n){size_t cap=n>((size_t)1<<20)?n:((size_t)1<<20);c=malloc(sizeof*c+cap);if(!c)return NULL;c->next=p->chunks;c->used=0;c->cap=cap;p->chunks=c;}void*r=c->data+c->used;c->used+=n;return r;}
static void *arena_grow(Parser *p,const void *old,size_t used,size_t cap){void*r=arena_alloc(p,cap);if(r&&used)memcpy(r,old,used);return r;}
static void arena_free(Parser *p){while(p->chunks){Chunk*c=p->chunks;p->chunks=c->next;free(c);}}
static void fail(Parser *p,const char *code,const char *msg) { if (p->d && !p->d->code[0]) { p->d->line=p->line; p->d->column=p->col; snprintf(p->d->code,sizeof p->d->code,"%s",code); snprintf(p->d->message,sizeof p->d->message,"%s",msg); } }
static char peek(Parser *p){return p->i<p->n?p->p[p->i]:0;}
static char take(Parser *p){char c=peek(p);if(c){p->i++;if(c=='\n'){p->line++;p->col=1;}else p->col++;}return c;}
static void ws(Parser *p){while(peek(p)==' '||peek(p)=='\t'||peek(p)=='\r'||peek(p)=='\n')take(p);}
static void jfree(JNode *x){(void)x;}
static JNode *node(Parser*p,JKind k){JNode*x=arena_alloc(p,sizeof*x);if(!x){fail(p,"E_MEMORY","out of memory");return NULL;}memset(x,0,sizeof*x);x->kind=k;x->line=p->line;x->col=p->col;return x;}
static bool push(Parser*p,JNode*x,JNode*y){if(x->n==x->cap){size_t c=x->cap?x->cap*2:4;JNode**v=arena_alloc(p,c*sizeof*v);if(v&&x->n)memcpy(v,x->v,x->n*sizeof*v);if(!v){fail(p,"E_MEMORY","out of memory");return false;}x->v=v;x->cap=c;}x->v[x->n++]=y;return true;}
static int hexval(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool utf8_valid(const unsigned char*s,size_t n){for(size_t i=0;i<n;){unsigned c=s[i++];if(c<0x80)continue;unsigned need=c>=0xC2&&c<=0xDF?1:c>=0xE0&&c<=0xEF?2:c>=0xF0&&c<=0xF4?3:99;if(need==99||i+need>n)return false;unsigned first=s[i];if((c==0xE0&&first<0xA0)||(c==0xED&&first>=0xA0)||(c==0xF0&&first<0x90)||(c==0xF4&&first>=0x90))return false;for(unsigned j=0;j<need;j++)if((s[i++]&0xC0)!=0x80)return false;}return true;}
static bool append_utf8(char*out,size_t*o,unsigned cp){if(cp<=0x7f)out[(*o)++]=(char)cp;else if(cp<=0x7ff){out[(*o)++]=(char)(0xc0|(cp>>6));out[(*o)++]=(char)(0x80|(cp&63));}else if(cp<=0xffff){out[(*o)++]=(char)(0xe0|(cp>>12));out[(*o)++]=(char)(0x80|((cp>>6)&63));out[(*o)++]=(char)(0x80|(cp&63));}else if(cp<=0x10ffff){out[(*o)++]=(char)(0xf0|(cp>>18));out[(*o)++]=(char)(0x80|((cp>>12)&63));out[(*o)++]=(char)(0x80|((cp>>6)&63));out[(*o)++]=(char)(0x80|(cp&63));}else return false;return true;}
static JNode *string_node(Parser*p){JNode*x=node(p,J_STR);if(!x)return NULL;take(p);size_t cap=32,o=0;x->s=arena_alloc(p,cap);if(!x->s){jfree(x);fail(p,"E_MEMORY","out of memory");return NULL;}for(;;){{size_t k=p->i;while(k<p->n&&(unsigned char)p->p[k]>=0x20&&p->p[k]!='"'&&p->p[k]!='\\')k++;size_t run=k-p->i;if(run){if(o+run+5>=cap){while(o+run+5>=cap)cap*=2;char*q=arena_grow(p,x->s,o,cap);if(!q){fail(p,"E_MEMORY","out of memory");goto bad;}x->s=q;}memcpy(x->s+o,p->p+p->i,run);o+=run;p->i+=run;p->col+=run;}}if(!peek(p)||peek(p)=='"')break;unsigned char c=(unsigned char)take(p);if(c<0x20){fail(p,"E_JSON","control character in string");goto bad;}if(c=='\\'){char e=take(p);switch(e){case '"':case '\\':case '/':c=(unsigned char)e;break;case 'b':c='\b';break;case 'f':c='\f';break;case 'n':c='\n';break;case 'r':c='\r';break;case 't':c='\t';break;case 'u':{unsigned cp=0;for(int k=0;k<4;k++){int h=hexval(take(p));if(h<0){fail(p,"E_JSON","invalid unicode escape");goto bad;}cp=(cp<<4)|(unsigned)h;}if(cp>=0xd800&&cp<=0xdbff){if(take(p)!='\\'||take(p)!='u'){fail(p,"E_JSON","unpaired high surrogate");goto bad;}unsigned lo=0;for(int k=0;k<4;k++){int h=hexval(take(p));if(h<0){fail(p,"E_JSON","invalid low surrogate");goto bad;}lo=(lo<<4)|(unsigned)h;}if(lo<0xdc00||lo>0xdfff){fail(p,"E_JSON","invalid low surrogate");goto bad;}cp=0x10000+((cp-0xd800)<<10)+(lo-0xdc00);}else if(cp>=0xdc00&&cp<=0xdfff){fail(p,"E_JSON","unpaired low surrogate");goto bad;}if(o+4>=cap){cap*=2;char*q=arena_grow(p,x->s,o,cap);if(!q){fail(p,"E_MEMORY","out of memory");goto bad;}x->s=q;}append_utf8(x->s,&o,cp);continue;}default:fail(p,"E_JSON","invalid string escape");goto bad;}}
if(o+5>=cap){cap*=2;char*q=arena_grow(p,x->s,o,cap);if(!q){fail(p,"E_MEMORY","out of memory");goto bad;}x->s=q;}x->s[o++]=(char)c;}if(take(p)!='"'){fail(p,"E_JSON","unterminated string");goto bad;}x->s[o]=0;x->slen=o;if(!utf8_valid((unsigned char*)x->s,o)){fail(p,"E_UTF8","invalid UTF-8 string");goto bad;}return x;bad:jfree(x);return NULL;}
static JNode *value(Parser*p);
static JNode *compound(Parser*p,JKind k){char end=k==J_OBJ?'}':']';take(p);JNode*x=node(p,k);if(!x)return NULL;ws(p);if(peek(p)==end){take(p);return x;}for(;;){if(k==J_OBJ){if(peek(p)!='"'){fail(p,"E_JSON","object key must be a string");goto bad;}JNode*key=string_node(p);if(!key)goto bad;ws(p);if(take(p)!=':'){jfree(key);fail(p,"E_JSON","expected ':'");goto bad;}ws(p);JNode*v=value(p);if(!v||!push(p,x,key)||!push(p,x,v)){jfree(key);jfree(v);goto bad;}}else{JNode*v=value(p);if(!v||!push(p,x,v)){jfree(v);goto bad;}}ws(p);char c=take(p);if(c==end)return x;if(c!=','){fail(p,"E_JSON","expected ',' or closing delimiter");goto bad;}ws(p);}bad:jfree(x);return NULL;}
static JNode *value(Parser*p){ws(p);char c=peek(p);if(c=='{')return compound(p,J_OBJ);if(c=='[')return compound(p,J_ARR);if(c=='"')return string_node(p);JKind k;const char*lit;if(c=='t'){k=J_TRUE;lit="true";}else if(c=='f'){k=J_FALSE;lit="false";}else if(c=='n'){k=J_NULL;lit="null";}else if(c=='-'||(c>='0'&&c<='9')){JNode*x=node(p,J_NUM);size_t st=p->i;if(c=='-')take(p);if(peek(p)=='0'){take(p);if(peek(p)>='0'&&peek(p)<='9'){jfree(x);fail(p,"E_JSON","leading zero in number");return NULL;}}else{if(peek(p)<'1'||peek(p)>'9'){jfree(x);fail(p,"E_JSON","invalid number");return NULL;}while(peek(p)>='0'&&peek(p)<='9')take(p);}if(peek(p)=='.'){take(p);if(peek(p)<'0'||peek(p)>'9'){jfree(x);fail(p,"E_JSON","fraction requires digits");return NULL;}while(peek(p)>='0'&&peek(p)<='9')take(p);}if(peek(p)=='e'||peek(p)=='E'){take(p);if(peek(p)=='+'||peek(p)=='-')take(p);if(peek(p)<'0'||peek(p)>'9'){jfree(x);fail(p,"E_JSON","exponent requires digits");return NULL;}while(peek(p)>='0'&&peek(p)<='9')take(p);}size_t n=p->i-st;x->s=arena_alloc(p,n+1);if(!x->s){jfree(x);fail(p,"E_MEMORY","out of memory");return NULL;}memcpy(x->s,p->p+st,n);x->s[n]=0;return x;}else{fail(p,"E_JSON","unexpected token");return NULL;}size_t n=strlen(lit);for(size_t i=0;i<n;i++)if(take(p)!=lit[i]){fail(p,"E_JSON","invalid literal");return NULL;}return node(p,k);}
static bool eq(const JNode*x,const char*s){return x&&x->kind==J_STR&&x->slen==strlen(s)&&!memcmp(x->s,s,x->slen);}
static JNode *field(Parser*p,JNode*x,const char*k){if(!x||x->kind!=J_OBJ){fail(p,"E_SCHEMA","expected object");return NULL;}JNode*r=NULL;for(size_t i=0;i<x->n;i+=2)if(eq(x->v[i],k)){if(r){fail(p,"E_DUPLICATE","duplicate object key");return NULL;}r=x->v[i+1];}if(!r){char b[160];snprintf(b,sizeof b,"missing field '%s'",k);fail(p,"E_SCHEMA",b);}return r;}
static bool exact_opt(Parser*p,JNode*x,const char*const*keys,size_t n,size_t req){if(!x||x->kind!=J_OBJ){fail(p,"E_SCHEMA","expected object");return false;}for(size_t i=0;i<x->n;i+=2){for(size_t j=0;j<i;j+=2)if(x->v[i]->kind==J_STR&&x->v[j]->kind==J_STR&&!strcmp(x->v[i]->s,x->v[j]->s)){fail(p,"E_DUPLICATE","duplicate object key");return false;}bool found=false;for(size_t j=0;j<n;j++)if(eq(x->v[i],keys[j]))found=true;if(!found){fail(p,"E_SCHEMA","unexpected object key");return false;}}for(size_t j=0;j<req;j++){bool found=false;for(size_t i=0;i<x->n;i+=2)if(eq(x->v[i],keys[j]))found=true;if(!found){fail(p,"E_SCHEMA","required object key missing");return false;}}return true;}
static bool has_key(JNode*x,const char*k){for(size_t i=0;i<x->n;i+=2)if(eq(x->v[i],k))return true;return false;}
static bool exact(Parser*p,JNode*x,const char*const*keys,size_t n){return exact_opt(p,x,keys,n,n);}
static bool arr(Parser*p,JNode*x){if(!x||x->kind!=J_ARR){fail(p,"E_SCHEMA","expected array");return false;}return true;}
static bool str(Parser*p,JNode*x,char**out){if(!x||x->kind!=J_STR){fail(p,"E_SCHEMA","expected string");return false;}*out=dupstr(x->s);if(!*out){fail(p,"E_MEMORY","out of memory");return false;}return true;}
static bool number(Parser*p,JNode*x,int64_t lo,int64_t hi,int64_t*out){if(!x||x->kind!=J_NUM){fail(p,"E_SCHEMA","expected integer");return false;}for(const char*q=x->s;*q;q++)if(*q=='.'||*q=='e'||*q=='E'){fail(p,"E_SCHEMA","integer value has a fraction or exponent");return false;}char*end;errno=0;long long n=strtoll(x->s,&end,10);if(errno||*end||n<lo||n>hi){fail(p,"E_RANGE","integer outside allowed range");return false;}*out=(int64_t)n;return true;}
static bool boolean(Parser*p,JNode*x,bool*out){if(x&&x->kind==J_TRUE){*out=true;return true;}if(x&&x->kind==J_FALSE){*out=false;return true;}fail(p,"E_SCHEMA","expected boolean");return false;}
static bool float_bits(Parser*p,JNode*x,uint64_t*out){if(!x||x->kind!=J_NUM){fail(p,"E_SCHEMA","expected float value");return false;}char*end;errno=0;double v=strtod(x->s,&end);if(*end||!isfinite(v)){fail(p,"E_RANGE","float value must be finite");return false;}memcpy(out,&v,sizeof v);return true;}
static bool parse_value(Parser*p,JNode*x,R6Value*out){static const char*const kinds[]={"Int","Float","String","Sym","Bool","Register","Label","None"};if(!x||x->kind!=J_OBJ){fail(p,"E_SCHEMA","value must be a kind/value object");return false;}JNode*k=NULL,*v=NULL;for(size_t i=0;i<x->n;i+=2){if(eq(x->v[i],"kind")){if(k){fail(p,"E_DUPLICATE","duplicate object key");return false;}k=x->v[i+1];}else if(eq(x->v[i],"value")){if(v){fail(p,"E_DUPLICATE","duplicate object key");return false;}v=x->v[i+1];}else{fail(p,"E_SCHEMA","unexpected object key in value");return false;}}if(!k){fail(p,"E_SCHEMA","value object is missing its kind");return false;}int found=-1;for(int i=0;i<8;i++)if(eq(k,kinds[i]))found=i;if(found<0){fail(p,"E_SCHEMA","unknown value kind");return false;}if(found==7){if(v){fail(p,"E_SCHEMA","None value must not carry a payload");return false;}out->kind=R6_VAL_NONE;return true;}if(!v){fail(p,"E_SCHEMA","value object is missing its value");return false;}int64_t z;switch(found){case 0:if(!number(p,v,INT64_MIN,INT64_MAX,&z))return false;out->as.i64=z;out->kind=R6_VAL_INT;break;case 1:if(!float_bits(p,v,&out->as.f64_bits))return false;out->kind=R6_VAL_FLOAT64;break;case 2:case 3:if(v->kind!=J_STR){fail(p,"E_SCHEMA","expected string value");return false;}out->as.string=malloc(v->slen+1);if(!out->as.string){fail(p,"E_MEMORY","out of memory");return false;}memcpy(out->as.string,v->s,v->slen+1);out->string_len=v->slen;out->kind=found==2?R6_VAL_STRING:R6_VAL_SYMBOL;break;case 4:if(!boolean(p,v,&out->as.boolean))return false;out->kind=R6_VAL_BOOL;break;case 5:case 6:if(!number(p,v,0,INT32_MAX,&z))return false;out->as.i64=z;out->kind=found==5?R6_VAL_REG:R6_VAL_LABEL;break;}return true;}

static bool strings(Parser*p,JNode*x,char***out,size_t*count){if(!arr(p,x))return false;*count=x->n;*out=calloc(x->n?x->n:1,sizeof(char*));if(!*out){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<x->n;i++)if(!str(p,x->v[i],&(*out)[i]))return false;return true;}
static bool parse_instruction(Parser*p,JNode*x,R6Instruction*i){static const char*const keys[]={"opcode","dest","operand1","operand2","operand3","elemKind","line"};if(!exact_opt(p,x,keys,7,6))return false;char*op=NULL;int64_t z;if(!str(p,field(p,x,"opcode"),&op))return false;int found=-1;for(int k=0;k<R6_OP_COUNT;k++)if(!strcmp(op,opcode_names[k]))found=k;if(found<0){fail(p,"E_OPCODE","opcode is not in IRv1");free(op);return false;}free(op);i->opcode=(R6Opcode)found;JNode*ln=has_key(x,"line")?field(p,x,"line"):NULL;if(ln){if(i->opcode!=R6_OP_DIV&&i->opcode!=R6_OP_MOD){fail(p,"E_SCHEMA","line is only allowed on div and mod");return false;}if(!number(p,ln,1,INT64_MAX,&z))return false;i->source_line=z;}if(!number(p,field(p,x,"dest"),-1,INT32_MAX,&z))return false;i->dest=(int32_t)z;i->has_dest=z>=0;if(!parse_value(p,field(p,x,"operand1"),&i->operands[0])||!parse_value(p,field(p,x,"operand2"),&i->operands[1])||!parse_value(p,field(p,x,"operand3"),&i->operands[2]))return false;if(!number(p,field(p,x,"elemKind"),0,5,&z))return false;i->elem_kind=(int32_t)z;i->line=x->line;i->column=x->col;return true;}
static bool parse_function(Parser*p,JNode*x,R6Function*f){static const char*const keys[]={"name","params","paramTypes","instructions","registerCount","registerTypes","returnType","isExtern","routeMethod","routePath","routeHasLimit","routeLimitRate","routeLimitWindowMs","routeLimitBurst"};if(!exact(p,x,keys,14))return false;size_t pt_len=0;int64_t z;if(!str(p,field(p,x,"name"),&f->name)||!strings(p,field(p,x,"params"),&f->params,&f->param_count)||!strings(p,field(p,x,"paramTypes"),&f->param_types,&pt_len))return false;if(pt_len!=f->param_count){fail(p,"E_SCHEMA","params and paramTypes length mismatch");return false;}JNode*ins=field(p,x,"instructions");if(!arr(p,ins))return false;f->instruction_count=ins->n;f->instructions=calloc(ins->n?ins->n:1,sizeof*f->instructions);if(!f->instructions){fail(p,"E_MEMORY","out of memory");return false;}for(size_t k=0;k<ins->n;k++)if(!parse_instruction(p,ins->v[k],&f->instructions[k]))return false;if(!number(p,field(p,x,"registerCount"),0,INT32_MAX,&z))return false;f->register_count=(int32_t)z;if(!strings(p,field(p,x,"registerTypes"),&f->register_types,&f->register_type_count))return false;if(f->register_type_count!=(size_t)f->register_count){fail(p,"E_SCHEMA","registerCount and registerTypes length mismatch");return false;}if(!str(p,field(p,x,"returnType"),&f->return_type)||!boolean(p,field(p,x,"isExtern"),&f->is_extern))return false;if(!str(p,field(p,x,"routeMethod"),&f->route.method)||!str(p,field(p,x,"routePath"),&f->route.path)||!boolean(p,field(p,x,"routeHasLimit"),&f->route.has_limit))return false;if(!number(p,field(p,x,"routeLimitRate"),INT32_MIN,INT32_MAX,&f->route.limit_rate)||!number(p,field(p,x,"routeLimitWindowMs"),INT32_MIN,INT32_MAX,&f->route.limit_window_ms)||!number(p,field(p,x,"routeLimitBurst"),INT32_MIN,INT32_MAX,&f->route.limit_burst))return false;bool plain=!f->route.method[0],empty_path=!f->route.path[0];if(plain!=empty_path||(plain&&(f->route.has_limit||f->route.limit_rate||f->route.limit_window_ms||f->route.limit_burst))){fail(p,"E_SCHEMA","route fields are inconsistent");return false;}f->has_route=!plain;return true;}
static bool parse_model(Parser*p,JNode*x,R6Model*m){static const char*const keys[]={"name","fields","typeParams"};static const char*const fk[]={"name","typeName"};if(!exact(p,x,keys,3)||!str(p,field(p,x,"name"),&m->name))return false;JNode*fs=field(p,x,"fields");if(!arr(p,fs))return false;m->field_count=fs->n;m->fields=calloc(fs->n?fs->n:1,sizeof*m->fields);if(!m->fields){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<fs->n;i++){JNode*y=fs->v[i];if(!exact(p,y,fk,2)||!str(p,field(p,y,"name"),&m->fields[i].name)||!str(p,field(p,y,"typeName"),&m->fields[i].type_name))return false;}if(!strings(p,field(p,x,"typeParams"),&m->type_params,&m->type_param_count))return false;if(m->type_param_count){fail(p,"E_UNSPECIFIED","generic model parameters are UNSPECIFIED");return false;}return true;}
static bool parse_type(Parser*p,JNode*x,R6Type*t){static const char*const keys[]={"name","kind","variants","richVariants","methods"};if(!exact(p,x,keys,5)||!str(p,field(p,x,"name"),&t->name)||!str(p,field(p,x,"kind"),&t->kind)||!strings(p,field(p,x,"variants"),&t->variants,&t->variant_count)||!strings(p,field(p,x,"richVariants"),&t->rich_variants,&t->rich_variant_count)||!strings(p,field(p,x,"methods"),&t->methods,&t->method_count))return false;if(t->method_count){fail(p,"E_UNSPECIFIED","type methods are UNSPECIFIED");return false;}return true;}
static bool parse_global(Parser*p,JNode*x,R6Global*g){static const char*const keys[]={"name","value","typeName"};if(!exact(p,x,keys,3)||!str(p,field(p,x,"name"),&g->name)||!parse_value(p,field(p,x,"value"),&g->value)||!str(p,field(p,x,"typeName"),&g->type_name))return false;return true;}
static bool parse_module(Parser*p,JNode*x,R6Module*m){static const char*const keys[]={"functions","globals","models","types","migrations","sourceName"};if(!exact_opt(p,x,keys,6,5))return false;if(has_key(x,"sourceName")){if(!str(p,field(p,x,"sourceName"),&m->source_name))return false;}else{m->source_name=dupstr("");if(!m->source_name){fail(p,"E_MEMORY","out of memory");return false;}}JNode*a=field(p,x,"functions");if(!arr(p,a))return false;m->function_count=a->n;m->functions=calloc(a->n?a->n:1,sizeof*m->functions);if(!m->functions){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<a->n;i++)if(!parse_function(p,a->v[i],&m->functions[i]))return false;a=field(p,x,"globals");if(!arr(p,a))return false;m->global_count=a->n;m->globals=calloc(a->n?a->n:1,sizeof*m->globals);if(!m->globals){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<a->n;i++)if(!parse_global(p,a->v[i],&m->globals[i]))return false;a=field(p,x,"models");if(!arr(p,a))return false;m->model_count=a->n;m->models=calloc(a->n?a->n:1,sizeof*m->models);if(!m->models){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<a->n;i++)if(!parse_model(p,a->v[i],&m->models[i]))return false;a=field(p,x,"types");if(!arr(p,a))return false;m->type_count=a->n;m->types=calloc(a->n?a->n:1,sizeof*m->types);if(!m->types){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<a->n;i++)if(!parse_type(p,a->v[i],&m->types[i]))return false;if(!strings(p,field(p,x,"migrations"),&m->migrations,&m->migration_count))return false;return true;}

/* D-M1-64: validation finds functions by name and labels by number through
 * hash tables built once, instead of scanning the module for every call and
 * the function for every jump. */
static uint64_t name_hash(const char*s){uint64_t h=1469598103934665603ull;while(*s){h^=(unsigned char)*s++;h*=1099511628211ull;}return h;}
typedef struct{int32_t*slots;size_t n;}FnIndex;
static void fn_index_free(FnIndex*x){free(x->slots);x->slots=NULL;x->n=0;}
static int32_t fn_index_find(const FnIndex*x,const R6Module*m,const char*name){size_t h=(size_t)(name_hash(name)&(x->n-1));while(x->slots[h]>=0){if(!strcmp(m->functions[x->slots[h]].name,name))return x->slots[h];h=(h+1)&(x->n-1);}return -1;}
static bool fn_index_build(FnIndex*x,const R6Module*m,bool*duplicate){size_t i;x->n=16;while(x->n<m->function_count*2+2)x->n*=2;x->slots=malloc(x->n*sizeof*x->slots);if(!x->slots)return false;for(i=0;i<x->n;i++)x->slots[i]=-1;*duplicate=false;for(i=0;i<m->function_count;i++){size_t h;if(fn_index_find(x,m,m->functions[i].name)>=0){*duplicate=true;return true;}h=(size_t)(name_hash(m->functions[i].name)&(x->n-1));while(x->slots[h]>=0)h=(h+1)&(x->n-1);x->slots[h]=(int32_t)i;}return true;}
static const R6Function *module_function(const FnIndex*x,const R6Module*m,const char*name){int32_t k=fn_index_find(x,m,name);return k<0?NULL:&m->functions[k];}
typedef struct{int32_t*key;unsigned char*seen;size_t n,cap;}LabelSet;
static void label_set_free(LabelSet*x){free(x->key);free(x->seen);x->key=NULL;x->seen=NULL;x->n=x->cap=0;}
static size_t label_slot(const LabelSet*x,int32_t label){size_t h=(size_t)(((uint32_t)label*2654435761u)&(x->n-1));while(x->key[h]>=0&&x->key[h]!=label)h=(h+1)&(x->n-1);return h;}
static bool label_set_reset(LabelSet*x,const R6Function*f){size_t n=16,i;while(n<f->instruction_count*2+2)n*=2;if(n>x->cap){int32_t*k=realloc(x->key,n*sizeof*k);unsigned char*sn;if(!k)return false;x->key=k;sn=realloc(x->seen,n);if(!sn)return false;x->seen=sn;x->cap=n;}x->n=n;for(i=0;i<n;i++){x->key[i]=-1;x->seen[i]=0;}for(i=0;i<f->instruction_count;i++){const R6Instruction*y=&f->instructions[i];if(y->opcode==R6_OP_LABEL&&y->operands[0].kind==R6_VAL_LABEL)x->key[label_slot(x,y->operands[0].as.i32)]=y->operands[0].as.i32;}return true;}
static bool label_set_first(LabelSet*x,int32_t label){size_t h=label_slot(x,label);if(x->seen[h])return false;x->seen[h]=1;return true;}
static bool label_set_has(const LabelSet*x,int32_t label){return x->key[label_slot(x,label)]==label;}
static bool opcode_needs_dest(R6Opcode op){switch(op){case R6_OP_LOAD_CONST:case R6_OP_LOAD_VAR:case R6_OP_COPY:case R6_OP_ADD:case R6_OP_SUB:case R6_OP_MUL:case R6_OP_DIV:case R6_OP_MOD:case R6_OP_EQ:case R6_OP_NE:case R6_OP_LT:case R6_OP_LE:case R6_OP_GT:case R6_OP_GE:case R6_OP_AND_OP:case R6_OP_OR_OP:case R6_OP_NOT_OP:case R6_OP_NEG:case R6_OP_LIST_CREATE:case R6_OP_LIST_LEN:case R6_OP_LIST_GET:case R6_OP_LIST_POP:case R6_OP_LOAD_FIELD:case R6_OP_RESULT_OK:case R6_OP_RESULT_ERR:case R6_OP_RESULT_IS_OK:case R6_OP_RESULT_UNWRAP:case R6_OP_RESULT_UNWRAP_ERR:case R6_OP_UNION_GET_TAG:case R6_OP_UNION_GET_DATA:case R6_OP_BIT_AND:case R6_OP_BIT_OR:case R6_OP_BIT_XOR:case R6_OP_SHL:case R6_OP_SHR:case R6_OP_BIT_NOT:return true;default:return false;}}
static bool validate_module(Parser*p,R6Module*m,const FnIndex*fx,LabelSet*ls){for(size_t i=0;i<m->global_count;i++)for(size_t j=0;j<i;j++)if(!strcmp(m->globals[i].name,m->globals[j].name)){fail(p,"E_DUPLICATE","duplicate global name");return false;}for(size_t i=0;i<m->model_count;i++)for(size_t j=0;j<i;j++)if(!strcmp(m->models[i].name,m->models[j].name)){fail(p,"E_DUPLICATE","duplicate model name");return false;}for(size_t i=0;i<m->model_count;i++)for(size_t j=0;j<m->function_count;j++)if(!strcmp(m->models[i].name,m->functions[j].name)){fail(p,"E_DUPLICATE","model name collides with a function name");return false;}for(size_t i=0;i<m->type_count;i++)for(size_t j=0;j<i;j++)if(!strcmp(m->types[i].name,m->types[j].name)){fail(p,"E_DUPLICATE","duplicate type name");return false;}for(size_t i=0;i<m->type_count;i++)for(size_t j=0;j<m->function_count;j++)if(!strcmp(m->types[i].name,m->functions[j].name)){fail(p,"E_DUPLICATE","type name collides with a function name");return false;}for(size_t i=0;i<m->type_count;i++)for(size_t j=0;j<m->model_count;j++)if(!strcmp(m->types[i].name,m->models[j].name)){fail(p,"E_DUPLICATE","type name collides with a model name");return false;}for(size_t i=0;i<m->type_count;i++){R6Type*t=&m->types[i];if(t->variant_count!=t->rich_variant_count){fail(p,"E_SCHEMA","type variants and richVariants have mismatched lengths");return false;}for(size_t v=0;v<t->variant_count;v++){char b[240];if(!t->variants[v][0]){fail(p,"E_SCHEMA","type variant name is empty");return false;}if(strlen(t->name)+strlen(t->variants[v])+6>=sizeof b){fail(p,"E_SCHEMA","type or variant name is too long for a tag constant");return false;}for(size_t u=0;u<v;u++)if(!strcmp(t->variants[v],t->variants[u])){fail(p,"E_DUPLICATE","duplicate variant name in type");return false;}for(size_t u=0;u<i;u++)for(size_t w=0;w<m->types[u].variant_count;w++)if(!strcmp(t->variants[v],m->types[u].variants[w])){fail(p,"E_DUPLICATE","variant name is declared by more than one type");return false;}for(size_t j=0;j<m->function_count;j++)if(!strcmp(t->variants[v],m->functions[j].name)){fail(p,"E_DUPLICATE","variant name collides with a function name");return false;}for(size_t j=0;j<m->model_count;j++)if(!strcmp(t->variants[v],m->models[j].name)){fail(p,"E_DUPLICATE","variant name collides with a model name");return false;}snprintf(b,sizeof b,"%s_TAG_%s",t->name,t->variants[v]);for(size_t j=0;j<m->global_count;j++)if(!strcmp(b,m->globals[j].name)){fail(p,"E_DUPLICATE","variant tag constant collides with a global name");return false;}for(size_t j=0;j<m->function_count;j++)if(!strcmp(b,m->functions[j].name)){fail(p,"E_DUPLICATE","variant tag constant collides with a function name");return false;}for(size_t j=0;j<m->model_count;j++)if(!strcmp(b,m->models[j].name)){fail(p,"E_DUPLICATE","variant tag constant collides with a model name");return false;}}}for(size_t f=0;f<m->function_count;f++){R6Function*x=&m->functions[f];if(x->has_route){fail(p,"E_UNSUPPORTED","Kynx routes are outside the M1 native subset");return false;}if(x->is_extern)continue;if(!label_set_reset(ls,x)){fail(p,"E_MEMORY","out of memory");return false;}size_t pending=0;for(size_t i=0;i<x->instruction_count;i++){R6Instruction*y=&x->instructions[i];if(!(y->opcode==R6_OP_NOP||y->opcode==R6_OP_BEGIN_BLOCK||y->opcode==R6_OP_END_BLOCK||y->opcode==R6_OP_LOAD_CONST||y->opcode==R6_OP_LOAD_VAR||y->opcode==R6_OP_DECL_VAR||y->opcode==R6_OP_STORE_VAR||y->opcode==R6_OP_ADD||y->opcode==R6_OP_SUB||y->opcode==R6_OP_MUL||y->opcode==R6_OP_DIV||y->opcode==R6_OP_MOD||y->opcode==R6_OP_EQ||y->opcode==R6_OP_NE||y->opcode==R6_OP_LT||y->opcode==R6_OP_LE||y->opcode==R6_OP_GT||y->opcode==R6_OP_GE||y->opcode==R6_OP_AND_OP||y->opcode==R6_OP_OR_OP||y->opcode==R6_OP_NOT_OP||y->opcode==R6_OP_NEG||y->opcode==R6_OP_COPY||y->opcode==R6_OP_JUMP||y->opcode==R6_OP_JUMP_IF_FALSE||y->opcode==R6_OP_LABEL||y->opcode==R6_OP_ARG||y->opcode==R6_OP_CALL||y->opcode==R6_OP_RET||y->opcode==R6_OP_LIST_CREATE||y->opcode==R6_OP_LIST_PUSH||y->opcode==R6_OP_LIST_LEN||y->opcode==R6_OP_LIST_GET||y->opcode==R6_OP_LIST_SET||y->opcode==R6_OP_LIST_POP||y->opcode==R6_OP_LOAD_FIELD||y->opcode==R6_OP_STORE_FIELD||y->opcode==R6_OP_RESULT_OK||y->opcode==R6_OP_RESULT_ERR||y->opcode==R6_OP_RESULT_IS_OK||y->opcode==R6_OP_RESULT_UNWRAP||y->opcode==R6_OP_RESULT_UNWRAP_ERR||y->opcode==R6_OP_UNION_GET_TAG||y->opcode==R6_OP_UNION_GET_DATA||y->opcode==R6_OP_BIT_AND||y->opcode==R6_OP_BIT_OR||y->opcode==R6_OP_BIT_XOR||y->opcode==R6_OP_SHL||y->opcode==R6_OP_SHR||y->opcode==R6_OP_BIT_NOT)){if(y->opcode>=R6_OP_DB_GET&&y->opcode<=R6_OP_DB_WHERE){fail(p,"E_UNSUPPORTED","db_* opcodes are excluded: the pinned net runtime has no DB symbols");return false;}fail(p,"E_UNSUPPORTED","opcode is outside the current supported range");return false;}if(y->elem_kind&&!(y->opcode>=R6_OP_LIST_CREATE&&y->opcode<=R6_OP_LIST_POP)){fail(p,"E_SCHEMA","elem_kind only allowed on list opcodes");return false;}if((y->opcode==R6_OP_LOAD_FIELD||y->opcode==R6_OP_STORE_FIELD)&&!(y->operands[1].kind==R6_VAL_SYMBOL||y->operands[1].kind==R6_VAL_STRING)){fail(p,"E_SCHEMA","field reference must be a Symbol or String");return false;}if(opcode_needs_dest(y->opcode)&&!y->has_dest){char b[96];snprintf(b,sizeof b,"%s requires a destination (dest >= 0)",opcode_names[y->opcode]);fail(p,"E_SCHEMA",b);return false;}if(y->opcode==R6_OP_CALL){const R6Function*callee=(y->operands[0].kind==R6_VAL_SYMBOL||y->operands[0].kind==R6_VAL_STRING)?module_function(fx,m,y->operands[0].as.string):NULL;if(callee&&strcmp(callee->return_type,"void")!=0&&!y->has_dest){char b[128];snprintf(b,sizeof b,"call to non-void %s requires a destination",callee->name);fail(p,"E_SCHEMA",b);return false;}}if(y->has_dest&&y->dest>=x->register_count){fail(p,"E_RANGE","instruction destination register out of range");return false;}for(int a=0;a<3;a++)if(y->operands[a].kind==R6_VAL_REG&&y->operands[a].as.i32>=x->register_count){fail(p,"E_RANGE","operand register out of range");return false;}if(y->opcode==R6_OP_ARG&&y->has_dest){int64_t ix;if(y->operands[0].kind!=R6_VAL_INT){fail(p,"E_SCHEMA","arg parameter index must be an Int");return false;}ix=y->operands[0].as.i64;if(ix<0||(size_t)ix>=x->param_count){fail(p,"E_RANGE","arg parameter index out of range");return false;}}if(y->opcode==R6_OP_LABEL){if(y->operands[0].kind!=R6_VAL_LABEL){fail(p,"E_SCHEMA","label requires a Label operand");return false;}if(!label_set_first(ls,y->operands[0].as.i32)){fail(p,"E_DUPLICATE","duplicate label in function");return false;}}if(y->opcode==R6_OP_JUMP||y->opcode==R6_OP_JUMP_IF_FALSE){unsigned li=y->opcode==R6_OP_JUMP?0u:1u;if(y->operands[li].kind!=R6_VAL_LABEL){fail(p,"E_SCHEMA","jump target must be a Label operand");return false;}if(!label_set_has(ls,y->operands[li].as.i32)){fail(p,"E_SCHEMA","jump target label is not defined in the function");return false;}}if(y->opcode==R6_OP_CALL){if(y->operands[1].kind!=R6_VAL_INT){fail(p,"E_SCHEMA","call arity (operand2) must be an Int");return false;}int64_t arity=y->operands[1].as.i64;if(arity<0){fail(p,"E_RANGE","call arity must be non-negative");return false;}if((size_t)arity>pending){fail(p,"E_SCHEMA","call arity exceeds the pending argument count");return false;}pending-=(size_t)arity;}else if(y->opcode==R6_OP_ARG&&!y->has_dest)pending++;}}return true;}
static bool validate(Parser*p,R6Module*m){FnIndex fx={NULL,0};LabelSet ls={NULL,NULL,0,0};bool dup=false,ok;if(!fn_index_build(&fx,m,&dup)){fail(p,"E_MEMORY","out of memory");fn_index_free(&fx);return false;}if(dup){fail(p,"E_DUPLICATE","duplicate function name");fn_index_free(&fx);return false;}ok=validate_module(p,m,&fx,&ls);fn_index_free(&fx);label_set_free(&ls);return ok;}
void r6_module_free(R6Module*m){if(!m)return;free(m->source_name);for(size_t f=0;f<m->function_count;f++){R6Function*x=&m->functions[f];free(x->name);for(size_t i=0;i<x->param_count;i++){free(x->params[i]);free(x->param_types[i]);}free(x->params);free(x->param_types);for(size_t i=0;i<x->instruction_count;i++)for(int a=0;a<3;a++)if(x->instructions[i].operands[a].kind==R6_VAL_STRING||x->instructions[i].operands[a].kind==R6_VAL_SYMBOL)free(x->instructions[i].operands[a].as.string);free(x->instructions);for(size_t i=0;i<x->register_type_count;i++)free(x->register_types[i]);free(x->register_types);free(x->return_type);free(x->route.method);free(x->route.path);}free(m->functions);for(size_t i=0;i<m->global_count;i++){free(m->globals[i].name);free(m->globals[i].type_name);if(m->globals[i].value.kind==R6_VAL_STRING||m->globals[i].value.kind==R6_VAL_SYMBOL)free(m->globals[i].value.as.string);}free(m->globals);for(size_t i=0;i<m->model_count;i++){free(m->models[i].name);for(size_t j=0;j<m->models[i].field_count;j++){free(m->models[i].fields[j].name);free(m->models[i].fields[j].type_name);}free(m->models[i].fields);for(size_t j=0;j<m->models[i].type_param_count;j++)free(m->models[i].type_params[j]);free(m->models[i].type_params);}free(m->models);for(size_t i=0;i<m->type_count;i++){R6Type*t=&m->types[i];free(t->name);free(t->kind);for(size_t j=0;j<t->variant_count;j++)free(t->variants[j]);for(size_t j=0;j<t->rich_variant_count;j++)free(t->rich_variants[j]);for(size_t j=0;j<t->method_count;j++)free(t->methods[j]);free(t->variants);free(t->rich_variants);free(t->methods);}free(m->types);for(size_t i=0;i<m->migration_count;i++)free(m->migrations[i]);free(m->migrations);memset(m,0,sizeof*m);}
static bool elision_marker(const char*data,size_t n){for(size_t i=0;i+4<n;i++)if((unsigned char)data[i]==0xe2&&(unsigned char)data[i+1]==0x80&&(unsigned char)data[i+2]==0xa6&&data[i+3]=='['){size_t j=i+4;while(j<n&&data[j]>='0'&&data[j]<='9')j++;if(j>i+4&&j+7<=n&&!memcmp(data+j," chars]",7))return true;}return false;}
bool r6_ir_parse(const char*data,size_t length,R6Module*out,R6Diagnostic*d){if(!out||(!data&&length))return false;memset(out,0,sizeof*out);if(d)memset(d,0,sizeof*d);Parser p={data,length,0,1,1,d,NULL};if(!length||data[length-1]!='\n'){fail(&p,"E_JSON","document must end with LF");return false;}if(length>=3&&(unsigned char)data[0]==0xef&&(unsigned char)data[1]==0xbb&&(unsigned char)data[2]==0xbf){fail(&p,"E_JSON","UTF-8 BOM is not allowed");return false;}if(elision_marker(data,length)){fail(&p,"E_JSON","document contains an authoring-tool elision marker");return false;}JNode*root=value(&p);if(root){ws(&p);if(p.i!=p.n){fail(&p,"E_JSON","trailing bytes after root value");root=NULL;}}if(!root){arena_free(&p);return false;}bool ok=true;if(root->kind==J_OBJ)for(size_t i=0;i<root->n;i+=2)if(eq(root->v[i],"format")){fail(&p,"E_FORMAT","superseded R6 draft format; expected irVersion + module");ok=false;}if(ok){static const char*const rk[]={"irVersion","module"};ok=exact(&p,root,rk,2);if(ok&&!eq(field(&p,root,"irVersion"),"1")){fail(&p,"E_VERSION","unsupported IR version (R6 supports the string \"1\")");ok=false;}if(ok)ok=parse_module(&p,field(&p,root,"module"),out);}if(ok)ok=validate(&p,out);arena_free(&p);if(!ok)r6_module_free(out);return ok;}
